# Generated by PlatformIO prebuild script. Firmware embeds a vetted collector snapshot.
from pathlib import Path
import base64
import hashlib
import json

Import("env")
base = Path(env.subst("$PROJECT_DIR")).resolve()
collector = base.parent / "collectors" / "windows" / "Collect-Inventory.ps1"
result = base / "include" / "generated_collector.h"
source = collector.read_bytes()
sha = hashlib.sha256(source).hexdigest().upper()
b64 = base64.b64encode(source).decode("ascii")

# Built-in port selection is intentionally limited to the Espressif USB VID.
# Do not enumerate, open or transmit to unrelated COM ports (PLC etc.).
# No network download, no permanent policy change and no -ExecutionPolicy Bypass.
bootstrap = (
    "$ErrorActionPreference='Stop';"
    "$c=@(Get-CimInstance Win32_PnPEntity|?{$_.PNPDeviceID -match 'VID_303A' -and $_.Name -match 'COM[0-9]+'}|%{[regex]::Match($_.Name,'COM[0-9]+').Value});"
    "if($c.Count -ne 1){throw 'CDC'};"
    "$p=$c[0];"
    "$s=[IO.Ports.SerialPort]::new($p,115200);"
    "$s.ReadTimeout=15000;$s.DtrEnable=$true;$s.Open();try{"
    "$s.WriteLine('SCRIPT');$b='';"
    "while(($l=$s.ReadLine().Trim()) -ne 'ENDSCRIPT'){$b+=$l};"
    # Same CDC handle is handed to collector, not reopened.
    "$a=[Convert]::FromBase64String($b);"
    "if((Get-FileHash -InputStream ([IO.MemoryStream]::new($a)) -Algorithm SHA256).Hash -ne '"+sha+"'){throw 'SHA'};"
    "$f=Join-Path $env:TEMP 'AdminToolkit-Collect.ps1';"
    # Windows PowerShell 5.1 decodes BOM-less .ps1 in the local ANSI code page.
    # Keep the SHA-256 check on the original source bytes and add UTF-8 BOM on disk.
    "[IO.File]::WriteAllBytes($f,([byte[]]@(239,187,191)+$a));"
    # Restricted on an unmanaged workstation would block the hash-verified
    # local .ps1. Change only this process, without writing CurrentUser or
    # LocalMachine registry keys, and restore the exact previous Process scope.
    # An explicit GPO restriction is never overridden.
    "$o=Get-ExecutionPolicy -Scope Process;$t=0;try{"
    "if((Get-ExecutionPolicy) -eq 'Restricted'){"
    "if(Get-ExecutionPolicy -List|?{$_.Scope -like '*Policy' -and $_.ExecutionPolicy -ne 'Undefined'}){throw 'GPO'};"
    "$t=1;Set-ExecutionPolicy -Scope Process RemoteSigned -Force;"
    "};"
    "& $f -Port $p -OpenSerial $s -Mode Fast -MaxPnpDevices 10"
    "}finally{try{if($t){Set-ExecutionPolicy -Scope Process $o -Force}}"
    "finally{Remove-Item -LiteralPath $f -Force -ea SilentlyContinue}}"
    "}finally{$s.Dispose()}"
)
bootstrap_full = bootstrap.replace(' -Mode Fast -MaxPnpDevices 10', ' -Mode Full -MaxPnpDevices 25')
bootstrap_hardware = bootstrap.replace(' -Mode Fast -MaxPnpDevices 10', ' -Mode Hardware -MaxPnpDevices 10')
if not bootstrap.isascii() or not bootstrap_full.isascii() or not bootstrap_hardware.isascii() or '\n' in bootstrap or '\r' in bootstrap or ')BOOT"' in bootstrap:
    raise ValueError('Invalid bootstrap')
# A fixed raw string is easier to audit than hand-escaped C literals.
result.parent.mkdir(parents=True,exist_ok=True)
text = (
    '#pragma once\n'
    '// AUTOMATICALLY GENERATED. DO NOT EDIT. SHA256: '+sha+'\n'
    'static const char kCollectorBase64[] PROGMEM =\n'
    + '\n'.join('  '+json.dumps(b64[i:i+128]) for i in range(0,len(b64),128))+';\n'
    'static const char kBootstrapFast[] PROGMEM = R"BOOT('+bootstrap+')BOOT";\n'
    'static const char kBootstrapFull[] PROGMEM = R"BOOT('+bootstrap_full+')BOOT";\n'
     'static const char kBootstrapHardware[] PROGMEM = R"BOOT('+bootstrap_hardware+')BOOT";\n'
)
result.write_text(text,encoding='utf-8')
print('Embedded Windows collector:',len(source),'bytes; bootstrap:',len(bootstrap),'HID characters; SHA256:',sha)
